const views = {'runs':'Runs','projects':'Projects','detail':'Run details','timeline':'Run timeline','settings':'Run settings','runtimes':'Runtimes','config':'Configuration'};
const theme = document.body.dataset.theme;
const view = document.body.dataset.view;
const descriptions = {runs:'Approved work, from claim to human merge.',projects:'Project policy, capacity and delivery authority.',detail:'BAC-42 · Preserve source on interrupted recovery',timeline:'BAC-42 · Every attempt and transition, in order.',settings:'BAC-42 · Effective policy and the next agent attempt.',runtimes:'Execution inventory, ownership and compatibility.',config:'Role routing and estimated spend limits.'};
const badge = (text, warn=false) => `<span class="badge ${warn?'warning':''}">${text}</span>`;
const table = (headers, rows) => `<div class="scroll" role="region" aria-label="${views[view]} table" tabindex="0"><table><thead><tr>${headers.map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const panel = (title, body) => `<section class="panel"><h2>${title}</h2>${body}</section>`;
const stats = () => `<div class="stats"><div class="stat">Active runs<strong>3 <small>/ 6</small></strong><small>2 queued · project capacity</small></div><div class="stat">Context occupancy<strong>46%</strong><small>Current attempt · sampled 8s ago</small></div><div class="stat">Cumulative tokens<strong>182,430</strong><small>Across 4 invocations</small></div><div class="stat">Estimated cost<strong>≥ $4.82</strong><small>API-equivalent USD · incomplete usage</small></div></div>`;
const evidence = () => `<details><summary>Source, delivery and retained findings</summary><p>Branch fix/recovery · attempt 2 / rung 1 · elapsed 4m / timeout 30m · heartbeat 8 seconds ago.</p><p>Review finding R1: interrupted source must survive reconciliation. Severity: high · disposition: addressed in attempt 2. Independent review pending.</p><p>Artifact source-snapshot.json · SHA-256 <code>7bf2d01…a24c980</code> (abbreviated fixture hash). Full evidence is retained by the host.</p><p>Delivered fixture BAC-39: PR #81 awaits human merge. PR links in this prototype are placeholders; James owns merge.</p></details>`+`<details><summary>Evidence completeness</summary><p>Builder usage is present. One child invocation has no final usage report. Known cost is a lower bound; missing evidence is not zero usage.</p></details><details><summary>Source and policy</summary><p>Base 8ac20e1 · frozen Core profile · independent review required. Policy replacement invalidates affected evidence.</p></details><details><summary>Child agents · 1 active / 2 allowed</summary><p>Read-only child: inspect interrupted recovery. Depth 1. Host admission and accounting retained; no direct parent-tree writes.</p></details>`;
const runRows = () => [
 ['<a href="detail.html">BAC-42</a><small>Preserve source on recovery</small>','python-harness',badge('Implementing'),'46% · fresh','≥ $4.82'],
 ['<a href="detail.html?state=blocked">FRO-18</a><small>Repair empty project view</small>','frontend-harness',badge('Blocked',true),'Unavailable','$2.10'],
 ['<a href="detail.html?state=approval">BAC-39</a><small>Validate runtime package</small>','python-harness',badge('Awaiting approval',true),'31% · stale','$1.72'],
 ['<a href="detail.html">FRO-21</a><small>Table navigation</small>','frontend-harness',badge('Queued'),'Not started','Not started']].map((row,i)=>[row[0]+`<details><summary>Run signals</summary><p>Branch: ${['fix/recovery','fix/empty-view','chore/certify','feat/table-navigation'][i]}<br>Attempt / rung: ${i===3?'Not started':'2 / 1'}<br>Elapsed / timeout: ${i===3?'Not started':'4m / 30m'}<br>Tokens in / out: ${i===0?'160,000 / 22,430':i===3?'Not started':'Unavailable'}<br>Activity: ${['Editing source · heartbeat 8s ago','Evidence missing · stopped','Waiting for James · stale','Waiting for capacity'][i]}<br>PR: ${i===2?'#81 · awaits human merge':'Not delivered'}</p></details>`,...row.slice(1)]);
const settings = (project=false) => `<form><div class="fields"><label>Delivery profile<select name="profile"><option>Core</option><option>Prototype</option><option>Hardening</option></select></label><label>Model preset<select name="preset"><option>Volume</option><option>High confidence</option></select></label><label>Implementation mode<select name="mode"><option>Automatic</option><option>Approval</option></select></label><label>Workflow<select name="workflow"><option>Existing</option><option>Diagnosis</option></select></label><label>Active agent limit<input type="number" min="1" max="8" value="4" required></label><label>Child delegation<select><option>Disabled</option><option>Read-only</option><option>Isolated writable</option></select></label><label>Children per parent<input type="number" min="0" max="2" value="2" required></label><label>Delegation depth<select><option>1</option></select></label><label>Concurrency<input type="number" min="1" max="6" value="2" required></label>${project?`<label>Certification<select><option>Manual</option><option>Automatic</option></select></label><label>Certification configuration<input value="runtime-certification.toml"></label><label>Sandbox isolation<select><option>Shared</option><option>Per-run</option></select></label><label>Isolation evidence<input value="evidence/isolation.json"></label>`:""}<label>Test design<select><option>Enabled</option><option>Disabled</option></select></label></div><p>${project?'New runs inherit these defaults. Existing runs retain their snapshots.':'Inherited project capacity: 4 agents. Run settings may restrict project limits. Current work continues when settings change.'}</p><button>Save fixture settings</button> <button type="reset" class="secondary">Reset</button></form>`;
function content(){
 if(view==='runs')return stats()+`<div class="grid">${panel('Work in progress',table(['Ticket','Project','State','Context','Estimate'],runRows()))}${panel('Needs attention',`<p>${badge('1 blocked',true)}</p><p>FRO-18: gate evidence is incomplete. Inspect the missing report before resuming.</p><a href="detail.html?state=blocked">Inspect blocked run →</a><hr><p>1 invocation awaits James.</p><a href="settings.html?state=approval">Review approval →</a>`)}</div>`;
 if(view==='projects')return panel('Registered projects',table(['Project','Delivery','Run slots','Agent slots','Waiting'],[['python-harness','Core','2 / 3','3 / 4','1 agent approval'],['frontend-harness','Core','1 / 3','1 / 4','1 blocked'],['nemoclaw-dev','Prototype','0 / 1','0 / 2','None']]))+panel('Project defaults · python-harness',settings(true));
 if(view==='detail')return stats()+`<div class="grid"><div>${panel('Attempt 2 · Implementation',`<p><span class="live"></span>Applying recovery fix · started 10:42</p><progress value="46" max="100" aria-label="Context occupancy 46 percent"></progress><p>92,000 / 200,000 context tokens · fresh observation. Cumulative usage above includes previous attempts.</p><div class="actions"><button data-action="Suspend">Suspend fixture run</button><button class="secondary" data-action="Cancel">Cancel fixture run</button><button class="secondary" data-action="Resume">Resume fixture run</button><button class="secondary" data-action="Resume from planning">Resume from planning</button><button class="secondary" data-action="Retry now">Retry fixture now</button><a href="timeline.html">Open timeline →</a></div>`)}${panel('Verification and review',table(['Evidence','Status','Meaning'],[['Deterministic verification',badge('Pending'),'After implementation'],['Independent review',badge('Not started'),'Separate reviewer sandbox'],['Pull request',badge('Not available'),'James merges after delivery']]))}</div>${panel('Retained evidence',evidence()+`<p><a href="settings.html">Run settings →</a></p><details><summary>Artifacts and live tail</summary><p>attempt-2/events.jsonl · source-snapshot.json · policy.json</p><pre>10:42 host: attempt admitted
10:43 sandbox: editing source
10:44 host: usage observed</pre></details>`)}</div>`;
 if(view==='timeline')return panel('Runtime waterfall',`<div class="waterfall" role="img" aria-label="Builder active from 10:42 to 10:46; read-only child from 10:43 to 10:45; reviewer not started"><p>10:42 → 10:46 · elapsed wall time</p><div>Builder <span style="width:75%">4m · active</span></div><div>Read-only child <span style="width:40%;margin-left:15%">2m</span></div><div>Reviewer · not started</div></div>${table(['Tool call','Role','Started','Duration','Outcome'],[['read_file','Builder','10:42:12','0.2s','Complete'],['exec_command','Read-only child','10:43:08','18.4s','Complete'],['apply_patch','Builder','10:44:31','0.1s','Complete']])}`)+`<div class="grid">${panel('Execution timeline',`<ol class="timeline"><li><time>10:44 · sandbox / builder</time><strong>Implementation active</strong><p>Attempt 2 · context 46% · 8 seconds old</p></li><li><time>10:42 · host</time><strong>Runtime certified and attempt admitted</strong><p>Authority identity matched · 1 child slot reserved</p></li><li><time>10:39 · James</time><strong>Diagnosis attempt approved</strong><p>Invocation diagnosis:1 · approval recorded</p></li><li><time>10:37 · host</time><strong>Interrupted session reconciled</strong><p>Source retained · no duplicate external effects</p></li><li><time>10:30 · host</time><strong>Ticket claimed</strong><p>Readiness and human label checked</p></li></ol>`)}${panel('Agent and tool activity',evidence()+table(['Role','State'],[['Builder',badge('Active')],['Read-only child',badge('Inspecting')],['Reviewer','Not admitted']]))}</div>`;
 if(view==='settings')return panel('Invocation admission',`<form><label>Next invocation ID<input value="diagnosis:1" required></label><button>Approve fixture invocation</button></form>${table(['Invocation','Runtime','Usage','Estimate'],[['builder:2','Certified · active','160,000 input / 22,430 output','≥ $4.82'],['child:1','Read-only · interrupted','Final report unavailable','Unknown']])}`)+panel('Effective run settings',settings())+panel('Frozen authority',`<p>Core · snapshot 8ac20e1. Policy replacement requires a paused run and invalidates affected evidence.</p><button class="secondary" data-action="Pause required before replacing policy">Replace policy in fixture</button>`);
 if(view==='runtimes')return panel('Sandbox inventory',table(['Sandbox','Ownership / state','Layout','Certification','Runs'],[['factory-build-python-harness-2','Factory · running','Isolated worktree',badge('Certified'),'BAC-42'],['factory-review-frontend-harness','Factory · stopped','Review snapshot','Expired · recheck before launch','None'],['codex-james','Operator-owned','Human workspace','Not managed','None']]))+panel('Compatibility evidence',`<p>Identity binds sandbox generation, image, native package, authority, hooks and probe implementation. A changed identity requires new evidence.</p>${evidence()}`);
 return panel('Model routing',`<form>${table(['Role','Model','Effort'],['Implementation','Review','Diagnosis','Documentation','Test design'].map(r=>[r,`<label><span class="sr">${r} model</span><input aria-label="${r} model" value="gpt-6-astra" required></label>`,`<select aria-label="${r} effort"><option>high</option><option>xhigh</option></select>`]))}<div class="fields"><label>Run ceiling · estimated USD<input type="number" min="1" value="50" required></label><label>Warning · estimated USD<input type="number" min="0" value="30" required></label></div><p>API-equivalent estimates, not account charges. Missing pricing remains unknown.</p><button>Save fixture configuration</button></form>`)+panel('Configuration sources',`<p>Project registry: read-only inventory. Model routing: validated before saving. Existing run selections remain frozen.</p><a href="projects.html">Inspect project defaults →</a>`);
}
document.body.innerHTML=`<a class="skip" href="#main">Skip to content</a><div class="shell"><aside class="sidebar"><a class="brand" href="../index.html">▦ FACTORY</a><nav aria-label="Main">${Object.entries(views).map(([key,label])=>`<a href="${key}.html" ${key===view?'aria-current="page"':''}>${label}</a>`).join('')}</nav><footer>FIXTURE WORKSPACE<br>No production connections<br><br><a href="../index.html">Compare alternatives</a></footer></aside><main id="main"><div class="toolbar"><span>${{light:'01 / LIGHT WORKSPACE',dark:'02 / OPERATIONS CONSOLE',compact:'03 / COMPACT DASHBOARD'}[theme]} · FIXTURES ONLY</span><label>Preview state<select id="state"><option value="populated">Populated</option><option value="empty">Empty</option><option value="blocked">Blocked</option><option value="approval">Awaiting approval</option><option value="unavailable">Unavailable data</option></select></label></div><div class="heading"><div><h1>${views[view]}</h1><p>${descriptions[view]}</p></div><a href="../index.html">Compare designs</a></div><div id="status" role="status" aria-live="polite"></div><div id="content"></div></main></div>`;
const stateSelect=document.querySelector('#state');
stateSelect.value=new URLSearchParams(location.search).get('state')||'populated';
if(!stateSelect.value)stateSelect.value='populated';
function render(){const state=stateSelect.value;const status=document.querySelector('#status');status.innerHTML='';let html=content();if(state==='empty')html=panel('Nothing here yet',`<div class="empty"><h2>No ${views[view].toLowerCase()} to show</h2><p>This fixture has no records. No work has been started.</p><button data-action="Populated fixture loaded" id="load">Load populated fixture</button></div>`);if(state==='unavailable')html=panel('Data unavailable',`<div class="empty"><h2>Evidence could not be loaded</h2><p>Context, token usage and estimated cost are unknown. This is not an empty queue or a zero-cost run.</p><button id="load">Retry fixture request</button></div>`);if(state==='blocked')html=`<div class="notice"><strong>Blocked · evidence incomplete</strong>The runtime report is missing. James must decide how to resolve this hold. No automatic retry is authorized.</div>`+html;if(state==='approval')html=`<div class="notice"><strong>Waiting for James · diagnosis:1</strong>Approve the next agent attempt. Deterministic observation can continue.<p><button data-action="Next fixture attempt approved">Approve fixture attempt</button></p></div>`+html;document.querySelector('#content').innerHTML=html;document.querySelectorAll('form').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();status.textContent='Fixture settings saved. No production configuration changed.'}));document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{status.textContent=b.dataset.action+' · fixture only.'}));document.querySelector('#load')?.addEventListener('click',()=>{stateSelect.value='populated';render()});}
stateSelect.addEventListener('change',render);render();
if(theme==='dark')document.querySelector('.heading').insertAdjacentHTML('afterend', '<div class="ops-strip"><span class="live"></span><strong>LIVE OPERATIONS</strong><span>3 active</span><a href="detail.html?state=blocked">1 blocked</a><a href="settings.html?state=approval">1 approval waiting</a><a href="timeline.html">Latest transitions →</a></div>');
